INSERT INTO pyq_collections (id, slug, subject, title, exam_paper, year, is_premium, question_count, sort_order)
VALUES ('5acc6eef-cc20-45f0-be8e-c57f6618d943', 'upsc-gs1-2026-pyq', 'upsc-mains', 'UPSC GS Paper I — PYQ & Model Answers (2026)', 'gs1', 2026, true, 20, 2);

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('6446a30a-c1a0-4b36-8023-09d90c44e33d', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 1, NULL, '1', 10, 150, 'Analyze the importance of Ashokan inscriptions for reconstructing Mauryan history.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('6446a30a-c1a0-4b36-8023-09d90c44e33d', 'Ashokan inscriptions -- Major and Minor Rock Edicts, Pillar Edicts, and cave inscriptions spread across the subcontinent -- are the single most important primary source for reconstructing Mauryan history, precisely because they are contemporary, in Ashoka''s own words, and geographically dispersed enough to reveal the empire''s actual territorial extent.

Their importance is threefold. First, they establish chronology and identity: before James Prinsep deciphered Brahmi script in 1837, ''Devanampiya Piyadasi'' was not confidently linked to Ashoka; the edicts, cross-referenced with Buddhist chronicles (Mahavamsa, Dipavamsa), fixed his identity, regnal dates, and succession. Second, they map the empire''s real extent -- edicts found from Kandahar (Afghanistan) to Andhra and Karnataka trace Mauryan reach far more reliably than literary sources alone. Third, they reveal state ideology and policy directly -- the Kalinga edicts'' explicit remorse after the war, the Dhamma edicts'' welfare measures (medical care for humans and animals, tree planting, wells), and administrative edicts naming officials (Mahamattas, Rajukas) give a first-hand view of Mauryan governance literary sources like the Arthashastra only describe abstractly.

Their limitation is real too: they reflect state messaging, not neutral fact, and must be read alongside the Arthashastra and Greek accounts (Megasthenes) for a fuller, cross-checked picture -- which is exactly why historians treat inscriptional and literary evidence as complementary, not substitutable.', 'Strong answers name specific edict types and give concrete examples (Kalinga edicts, Prinsep''s decipherment) rather than a generic ''inscriptions are useful'' claim, and note the source''s limitation (state messaging) rather than treating it as unquestionably objective.', 'UPSC CSE Mains 2026, GS Paper I, Q1 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('79ccd7f8-3f45-4cdd-9ffc-4974e13dbe09', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 2, NULL, '2', 10, 150, 'Discuss the impact of Macaulay''s Minute on colonial administration and education in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('79ccd7f8-3f45-4cdd-9ffc-4974e13dbe09', 'Thomas Macaulay''s 1835 Minute on Education argued that English-medium Western education should replace state patronage of Sanskrit/Persian classical learning, on the explicit premise that English literature was superior and that the goal was to create, in his own words, a class ''Indian in blood and colour, but English in taste, opinions, morals and intellect'' to serve as intermediaries between the colonial state and the wider population.

Its administrative impact was direct: Governor-General Bentinck''s 1835 English Education Act adopted the Minute''s recommendation, redirecting the Company''s education funds toward English-medium institutions and downgrading indigenous classical learning from state priority to private pursuit. This produced the English-educated Indian middle class that would staff subordinate colonial administration -- clerks, translators, minor officials -- exactly the intermediary function Macaulay intended.

Its unintended long-run impact was the opposite of its purpose: English education exposed this same class to Enlightenment ideas of liberty, self-governance, and constitutionalism, and it was substantially this English-educated class -- not the classically trained elite -- that later founded and led the Indian National Congress and the nationalist movement. Macaulay''s policy is thus a classic case of a colonial intervention producing the intellectual tools of its own eventual opposition, alongside its more direct legacy of marginalizing indigenous knowledge systems and entrenching English as India''s administrative and elite-education language to this day.', 'Reward answers that name both the intended effect (an intermediary administrative class) and the unintended long-run consequence (nationalist leadership emerging from this same class) -- a one-sided answer covering only one side misses the question''s real analytical depth.', 'UPSC CSE Mains 2026, GS Paper I, Q2 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('80e8c605-62bd-4bf0-bc24-ef1b50e47c00', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 3, NULL, '3', 10, 150, 'The significance of the Gandhian movements lay in the masses they mobilized. Elucidate.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('80e8c605-62bd-4bf0-bc24-ef1b50e47c00', 'Gandhi''s distinctive contribution to the national movement was not a new ideology of independence -- that existed before him -- but a method (satyagraha) that, for the first time, was accessible enough to mobilize peasants, workers, women, and the urban poor at a scale earlier elite-led phases of the movement never reached.

Champaran (1917) and Kheda (1917-18) mobilized indigo and peasant cultivators around concrete local grievances, not abstract nationalism, proving mass mobilization was possible outside educated urban circles. Non-Cooperation (1920-22) was the first genuinely pan-Indian mass movement, drawing in students, lawyers, and -- through the linked Khilafat agitation -- Muslims alongside Hindus, at a scale the earlier Moderate and Extremist phases never achieved. Civil Disobedience''s Dandi March (1930) deliberately chose salt -- a good used by every household regardless of class or caste -- as its symbol, precisely to make participation universally accessible; women''s participation in salt-making and picketing during this phase marked a qualitative widening of who counted as a political actor. Quit India (1942), despite swift and severe repression, demonstrated the movement had become genuinely self-sustaining without centralized leadership, since most senior Congress leaders were arrested almost immediately.

The significance, therefore, is that Gandhi converted nationalism from an elite petitioning movement into a genuine mass movement -- and it was this scale of participation, not any single tactical victory, that made continued colonial rule politically unsustainable.', 'The question specifically asks about mass mobilization, not Gandhian philosophy in the abstract -- answers should name specific movements and specifically explain WHO was newly drawn in and why the method made that possible, rather than summarizing Gandhi''s ideology generally.', 'UPSC CSE Mains 2026, GS Paper I, Q3 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b8c49bd9-d075-4872-9af9-599b9de120d1', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 4, NULL, '4', 10, 150, 'What is the Fujiwhara effect? Explain its impact on the movement and intensity of tropical cyclones.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b8c49bd9-d075-4872-9af9-599b9de120d1', 'The Fujiwhara effect (named after Japanese meteorologist Sakuhei Fujiwhara, who first described it in 1921) occurs when two tropical cyclones pass within roughly 1,400 km of each other and begin to rotate around a common center, mutually influenced by each other''s circulation rather than moving independently.

Its effect on movement is the more dramatic and better-documented consequence: the two systems can rotate cyclonically around each other (in the Northern Hemisphere), sometimes merging into a single system if one is significantly weaker, or being flung onto an erratic, hard-to-forecast track if comparably matched -- this unpredictability is exactly why the Fujiwhara effect is a genuine operational forecasting challenge, since standard track-prediction models assume a single, independently-steered system.

Its effect on intensity is more variable and situation-dependent: if one storm is substantially stronger, it can draw moisture and energy away from the weaker system, weakening it or absorbing it entirely; conversely, interaction can sometimes disrupt the stronger storm''s own organized structure, weakening it too. There is no single universal intensity outcome -- the effect is best understood as primarily a track-altering phenomenon, with intensity changes as a secondary, case-dependent consequence, which is why real-world instances (such as interacting typhoons in the Northwest Pacific) are studied individually rather than fitted to one general intensity rule.', 'This is a factual/conceptual question -- answers should clearly separate the mechanism (mutual rotation around a common center) from its two distinct consequences (track alteration, which is consistent and well-documented, versus intensity change, which is variable) rather than blending the two into one vague description.', 'UPSC CSE Mains 2026, GS Paper I, Q4 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('745a063b-3dd1-48b8-8883-5a033ca1d8c2', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 5, NULL, '5', 10, 150, '"Tundra regions are ecologically fragile but economically important." Examine this statement critically.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('745a063b-3dd1-48b8-8883-5a033ca1d8c2', 'Tundra ecosystems -- found in Arctic high-latitude regions and on high mountains above the tree line -- are ecologically fragile because of a combination of extremely short growing seasons, permafrost that limits drainage and root depth, and very low biodiversity and species redundancy, meaning the loss of even one keystone species (a lichen, a caribou population) can disproportionately disrupt the whole food web with little capacity for the ecosystem to recover quickly.

Their economic importance is nonetheless substantial and growing. Tundra and sub-Arctic regions hold significant proven and prospective oil, gas, and mineral reserves (the Arctic National Wildlife Refuge and Siberian fields are prominent examples), and retreating sea ice is opening new shipping routes (the Northern Sea Route) and fishing grounds. Indigenous communities also depend directly on tundra ecosystems for reindeer herding, hunting, and fishing as a subsistence and cultural economy, distinct from industrial extraction.

The critical tension is that the very fragility making tundra ecologically significant is what industrial economic activity most threatens: permafrost thaw from both climate change and surface disturbance (drilling, roads) releases stored methane and carbon in a feedback loop that accelerates further warming, while oil spills or infrastructure in this environment take far longer to remediate than in more resilient biomes. The statement is therefore accurate but incomplete without this tension -- tundra''s fragility and its economic value are not two separate facts sitting side by side; the fragility is precisely what makes exploiting the economic value so consequential and hard to reverse.', 'This is explicitly a ''critically examine'' question -- a strong answer must go beyond listing fragility facts and economic facts separately, and must explicitly connect the two (the fragility is what makes the economic exploitation risky/consequential), which is what ''critical'' examination means here.', 'UPSC CSE Mains 2026, GS Paper I, Q5 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('3ed05fb2-c31c-4674-81c5-896aab0f0ee1', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 6, NULL, '6', 10, 150, 'Discuss the role of aeolian processes in desertification and land degradation.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('3ed05fb2-c31c-4674-81c5-896aab0f0ee1', 'Aeolian (wind-driven) processes -- deflation (removal of fine loose material), abrasion (wind-borne sand wearing down surfaces), and deposition (sand accumulation as dunes) -- are both a symptom and an active accelerant of desertification, not merely a passive feature of already-arid land.

Deflation strips the fine, nutrient-rich topsoil first, since silt and clay particles are lighter and more easily lifted than sand -- leaving behind a coarser, less fertile surface that supports even less vegetation, which in turn removes the root systems that would otherwise anchor remaining soil, creating a self-reinforcing degradation cycle. Abrasion damages remaining vegetation directly (sandblasting young shoots and leaves) and erodes exposed rock and soil structure, further reducing the land''s capacity to retain moisture or support plant growth. Deposition relocates the problem rather than resolving it -- advancing dunes bury agricultural land and water sources at the desert margin, which is the visible, dramatic face of desertification most associated with cases like the southern edge of the Sahara (the Sahel) and India''s own Thar Desert margins in Rajasthan.

Human activity accelerates all three processes -- overgrazing and deforestation remove the vegetation cover that would otherwise limit wind''s access to loose soil in the first place, which is why desertification is understood as a combination of a natural aeolian process and unsustainable land-use pressure acting together, not either factor alone.', 'Strong answers name the three distinct aeolian sub-processes (deflation, abrasion, deposition) individually rather than describing ''wind erosion'' as one undifferentiated phenomenon, and connect the natural process to human land-use drivers rather than presenting desertification as purely climatic.', 'UPSC CSE Mains 2026, GS Paper I, Q6 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c3b1f40a-6833-49a8-8c0c-64a7413c2cfb', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 7, NULL, '7', 10, 150, '"Water resources are both an asset and a source of conflict in South Asia." Examine with examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c3b1f40a-6833-49a8-8c0c-64a7413c2cfb', 'South Asia''s major river systems are foundational economic assets -- the Indus, Ganges, and Brahmaputra basins support irrigation for hundreds of millions, hydropower generation, and drinking water for the region''s largest population centers, making water arguably the single most important shared natural resource in South Asia.

This same resource is a persistent source of inter-state tension precisely because these rivers are transboundary, and upstream control creates leverage over downstream states. The Indus Waters Treaty (1960) between India and Pakistan, though historically resilient even through wars, has faced renewed strain over dam projects on western rivers allocated to Pakistan. The Ganges Water Treaty (1996) with Bangladesh addresses dry-season flow-sharing at the Farakka Barrage but recurring Bangladeshi concerns over reduced flow illustrate the treaty''s limits. The unresolved Teesta river-sharing dispute between India and Bangladesh remains a live diplomatic friction point. Within India itself, the Cauvery dispute between Karnataka and Tamil Nadu shows the same asset-versus-conflict dynamic operating at the sub-national level.

The pattern across all these cases is consistent: water''s shared, transboundary nature means one state''s or region''s development use of it structurally constrains another''s, and unlike most other economic assets, water cannot simply be substituted or imported when access is disputed -- which is exactly why water diplomacy in South Asia requires ongoing institutional management (treaties, joint commissions) rather than a one-time resolution.', 'The question asks for examples specifically -- answers naming only one treaty/dispute score lower than those citing multiple real, current examples across both international (Indus, Ganges, Teesta) and domestic (Cauvery) scales, showing the pattern is structural rather than a single isolated case.', 'UPSC CSE Mains 2026, GS Paper I, Q7 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page. Minor wording variant noted: Insights on India phrases the closing instruction as ''Examine this statement giving examples'' versus Drishti''s ''Examine with examples'' -- an immaterial difference in instruction wording, not in what is being asked.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('df8c7222-ba4b-4241-9724-d871b53272d6', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 8, NULL, '8', 10, 150, 'Unity in diversity remains the defining feature of Indian society despite the challenges from communalism and regionalism. Comment.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('df8c7222-ba4b-4241-9724-d871b53272d6', 'India''s ''unity in diversity'' refers to a shared civic and constitutional identity persisting across genuinely vast religious, linguistic, ethnic, and regional differences -- a diversity greater in scale than almost any other single nation-state, held together not by cultural homogeneity but by shared constitutional values, a common democratic process, and overlapping economic and social ties that cut across group lines.

Communalism -- the politicization of religious identity into a zero-sum, exclusionary basis for claims on the state -- has produced real fractures: Partition itself, periodic communal violence (Gujarat 2002, Muzaffarnagar 2013), and ongoing majoritarian-versus-minority political contestation. Regionalism has produced its own real strains: the Dravidian movement''s historical anti-Hindi-imposition politics, Khalistani separatism in Punjab''s past, and periodic secessionist sentiment in parts of the Northeast reflect genuine regional grievances about representation and resource-sharing, not manufactured discontent.

Despite these real and recurring challenges, the constitutional and institutional framework has proven resilient: free and fair elections have consistently produced peaceful transfers of power across every religious and regional line, linguistic reorganization of states (1956 onward) accommodated regional identity claims within the union rather than allowing them to become secessionist, and a shared economic space and internal migration continue to create everyday interdependence across group lines that no single communal or regional narrative has been able to fully dissolve. The defining feature, properly understood, is not the absence of these tensions but the constitutional and institutional capacity to accommodate them without the union itself fracturing.', 'A ''Comment'' instruction still expects a balanced view, not agreement by default -- strong answers give real, specific examples of both the challenges (not just naming ''communalism'' abstractly) and the accommodating mechanisms (linguistic reorganization, electoral continuity) that have preserved unity despite them.', 'UPSC CSE Mains 2026, GS Paper I, Q8 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('322df881-2bc8-42c0-bef8-d42ffad14047', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 9, NULL, '9', 10, 150, 'How do you understand disability? Substantiate the need for inclusive policy framework in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('322df881-2bc8-42c0-bef8-d42ffad14047', 'The modern understanding of disability has shifted from a purely medical model (disability as an individual physical/mental deficit to be treated or cured) to a social model, formalized in the UN Convention on the Rights of Persons with Disabilities (UNCRPD, which India ratified in 2007): disability is substantially produced by a mismatch between a person''s condition and an environment/society designed without them in mind, not solely an inherent property of the individual. A wheelchair user is disabled less by the wheelchair than by a building with no ramp.

India''s Rights of Persons with Disabilities Act, 2016 reflects this shift -- expanding recognized disability categories from 7 to 21, and mandating accessibility in public infrastructure, reflecting the social-model premise that the environment, not just the individual, must adapt.

The need for an inclusive policy framework follows directly from this understanding: if disability is partly environmentally produced, then policy''s job is not limited to individual welfare support (pensions, aids) but must also actively redesign the shared environment -- physical accessibility (ramps, transport), digital accessibility (screen-reader-compatible government services), educational inclusion (integrated rather than segregated schooling), and employment reservation. India''s continuing gaps -- inconsistent building-code enforcement, low actual employment-reservation compliance, patchy assistive-technology access -- show that the legal framework has moved ahead of the on-ground infrastructure and enforcement, meaning the social-model understanding is accepted in law but not yet fully realized in practice.', 'Strong answers explicitly name the medical-model-to-social-model shift (rather than only describing disability sympathetically) and connect that conceptual shift directly to why policy must go beyond welfare to environmental/infrastructural redesign -- the question''s two parts (understanding disability, and the case for policy) should be explicitly linked, not answered as two separate mini-essays.', 'UPSC CSE Mains 2026, GS Paper I, Q9 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page. Minor wording variant noted: Insights on India''s fuller closing clause (''...framework in India in this regard'') versus Drishti''s shorter version is an immaterial phrasing difference.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('bd5bf7c4-ea70-442e-90b3-a93e85504564', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 10, NULL, '10', 10, 150, 'Do you think digital technology promotes social empowerment? Explain with examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('bd5bf7c4-ea70-442e-90b3-a93e85504564', 'Digital technology has genuinely empowering effects when it removes a prior structural barrier to access, information, or voice. Direct Benefit Transfer (DBT), built on the JAM trinity (Jan Dhan bank accounts, Aadhaar identity, Mobile connectivity), has reduced leakage in welfare disbursement and given previously unbanked citizens -- disproportionately poor and rural -- direct control over their own benefit payments rather than dependence on intermediaries. Digital platforms have given historically marginalized voices (Dalit, women''s, and regional-language creators) direct reach to an audience without needing traditional media gatekeepers'' approval. UPI has extended low-cost financial transactions to small vendors and informal-sector workers who previously had no practical access to digital payment infrastructure.

The empowerment is not unconditional, however, and a fair answer must name the real limits. The digital divide -- along income, gender, rural-urban, and age lines -- means digital tools can widen existing inequality for those left offline, rather than closing it, if access itself remains unequal. Misinformation spreads through the same platforms that spread empowering information, and increased online visibility has also enabled new forms of harassment, particularly targeting women and minorities, that did not exist in the same form before.

The honest answer, then, is conditional: digital technology promotes social empowerment specifically where it is paired with genuine access, digital literacy, and safeguards against its own new harms -- it does not do so automatically or universally by its mere existence.', 'This is an opinion-based question (''Do you think'') -- examiners reward a clearly stated, reasoned position (here: conditional yes) over a noncommittal answer that only lists pros and cons without actually answering the question asked.', 'UPSC CSE Mains 2026, GS Paper I, Q10 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('62f6a293-815d-4415-9b5a-cfdde7ecbe1e', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 11, NULL, '11', 15, 250, 'Vijayanagara architecture exemplifies the amalgamation of past traditions with contemporary practices. Elucidate with examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('62f6a293-815d-4415-9b5a-cfdde7ecbe1e', 'Vijayanagara architecture (14th-17th century, centered at Hampi) is a genuine synthesis: it draws on preceding Dravidian temple traditions while innovating in scale, structure, and -- distinctively -- absorbing Indo-Islamic elements from contemporaneous Deccan Sultanates, producing a style recognizably continuous with the past yet visibly of its own moment.

From Dravidian tradition, Vijayanagara inherited and elaborated the temple complex model: the towering gopuram gateway, the vimana over the sanctum, and the mandapa hall -- all present in earlier Chola and Hoysala temple architecture. Vijayanagara''s distinctive contribution was scaling this up dramatically and adding new structural elements: the multi-pillared kalyana mandapa (ceremonial marriage hall) with elaborately carved rearing-horse and mythical-beast (yali) pillars, seen at the Vittala Temple, represents a genuine formal innovation beyond earlier Dravidian precedent, not mere repetition of it.

The ''contemporary practices'' half of the amalgamation is the empire''s well-documented absorption of Indo-Islamic architectural vocabulary from its Deccan Sultanate neighbors and rivals -- visible in secular structures like the Lotus Mahal and the Elephant Stables at the royal centre, which use true arches, domes, and vaulted ceilings entirely absent from the classical Dravidian temple vocabulary. This was not incidental borrowing but a deliberate stylistic choice for secular and courtly buildings specifically, kept distinct from the temple architecture that retained its Dravidian idiom -- itself evidence of a sophisticated, context-aware synthesis rather than an undifferentiated blending of styles.

The iconic stone chariot at Hampi, carved to represent a temple chariot in stone with a fixed, monumental form, exemplifies the whole pattern in miniature: a ritual object rooted in older temple-procession tradition, reimagined in a permanent, technically ambitious form unique to the Vijayanagara moment.', '''Elucidate with examples'' demands specific named structures (Vittala Temple, Lotus Mahal, Elephant Stables, the stone chariot), not a generic description of ''Hindu and Islamic influences blending.'' The strongest answers also note WHERE each tradition was applied (temple architecture stayed Dravidian; secular/courtly buildings absorbed Indo-Islamic elements) rather than implying uniform blending everywhere.', 'UPSC CSE Mains 2026, GS Paper I, Q11 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page. Minor wording variant noted: Drishti''s phrasing is ''amalgamation of past traditions with contemporary practices''; Insights on India''s is ''amalgamation of traditions with contemporary practices'' (omits ''past''). The question text above follows Drishti''s fuller wording; the substance asked is identical either way.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('86f8f09c-e29e-4bd6-a4aa-ba01592b3cef', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 12, NULL, '12', 15, 250, 'Linguistic reorganization of Indian States was driven by popular pressure from below. Comment.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('86f8f09c-e29e-4bd6-a4aa-ba01592b3cef', 'The States Reorganisation Act, 1956, which redrew India''s internal state boundaries substantially along linguistic lines, is best understood as a case where sustained popular mobilization from below forced the central government''s hand, rather than a plan the state initiated and implemented on its own preferred timeline.

The clearest evidence is the Andhra movement: the Congress-led central government initially resisted linguistic reorganization after Partition, worried it would encourage fissiparous tendencies. Potti Sriramulu''s fifty-eight-day fast for a separate Telugu-speaking state, ending in his death in December 1952, triggered such intense public reaction across the Telugu-speaking region that the government was compelled to concede Andhra State within weeks -- a direct, undeniable instance of grassroots pressure overriding the centre''s stated preference. This concession then created an immediate precedent other linguistic-regional movements (Marathi, Gujarati, Punjabi speakers) invoked to press their own claims, making the States Reorganisation Commission (1953) itself substantially a response to pressure already building, not a proactive central initiative.

The ''from below'' character is significant precisely because it distinguishes this reorganization from a purely administrative or technocratic redrawing of boundaries -- it reflects genuine popular attachment to linguistic-cultural identity as a legitimate basis for political organization, which the Indian state ultimately chose to accommodate constitutionally (through Article 3''s provision for altering state boundaries) rather than suppress.

A balanced answer should also note the limits of the ''purely popular pressure'' framing: the States Reorganisation Commission''s eventual recommendations still involved considerable central negotiation, compromise, and boundary-drawing judgment (Bombay State''s initial retention as bilingual before its 1960 split into Maharashtra and Gujarat shows the centre did not simply rubber-stamp every popular demand immediately or in the form first demanded) -- popular pressure was the primary driving force, but implementation still ran through central political calculation, not a pure, unmediated translation of popular will into new boundaries.', 'The Potti Sriramulu/Andhra case is the essential concrete evidence this answer needs -- an answer without it is arguing the claim in the abstract rather than substantiating it. The strongest answers also qualify the claim (noting the centre still exercised real judgment in implementation, e.g. Bombay State''s delayed split) rather than treating ''driven by popular pressure'' as meaning the centre had no independent role at all.', 'UPSC CSE Mains 2026, GS Paper I, Q12 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('7939d9ec-4175-424f-b39f-0a8460d783e6', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 13, NULL, '13', 15, 250, 'The model of planned economy was adopted in India to address the regional imbalances left behind by colonial rule. Comment.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('7939d9ec-4175-424f-b39f-0a8460d783e6', 'Colonial economic policy left independent India with severe, deliberately-produced regional imbalances: port-city regions (Bombay, Calcutta, Madras) and areas serving colonial extraction and export needs saw disproportionate infrastructure investment, while vast agrarian interior regions remained deliberately under-industrialized, since colonial policy generally favoured India as a raw-material source and captive market rather than a site of competing industrial development. Correcting this inherited imbalance was one explicit motivation -- though not the only one -- behind India''s post-independence turn to centralized economic planning.

The Second Five-Year Plan (1956-61), shaped substantially by the Mahalanobis model, prioritized heavy industry and public-sector investment specifically in backward and interior regions -- steel plants at Bhilai, Durgapur, and Rourkela, and later public-sector units deliberately sited away from the already-developed colonial port-city belt, reflect a conscious redistribution logic, not merely an efficiency-maximizing site-selection process. This was planning being used explicitly as a regional-equity tool, alongside its more commonly cited goals of rapid industrialization and reducing dependence on imports.

A balanced ''Comment'' answer must note this was not the sole driver of planning, nor was it fully successful. Planning was equally motivated by import-substitution industrialization, self-reliance (swadeshi-inflected economic nationalism), and Nehruvian socialist ideology independent of the regional-imbalance question specifically. And despite public-sector siting efforts, significant regional imbalance persisted and in some respects widened over the plan era -- states with pre-existing infrastructure and human-capital advantages (Maharashtra, Gujarat, Tamil Nadu) generally continued to out-pace the more agrarian, less-industrialized states planning had specifically targeted, showing that public investment location alone could not fully offset deeper structural and historical disadvantages inherited from the colonial period.

The statement is therefore true as a partial account of planning''s motivation, but overstates it as the primary or sufficient explanation for either planning''s adoption or its regional-equity outcomes.', 'This is a ''Comment'' question inviting critical engagement, not simple agreement -- strong answers name planning''s other real motivations (import substitution, self-reliance, socialist ideology) alongside the regional-imbalance goal, and honestly note planning''s incomplete success at actually closing regional gaps, rather than presenting planned-economy adoption as a straightforward, fully successful solution to colonial-era imbalance.', 'UPSC CSE Mains 2026, GS Paper I, Q13 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('441540d2-4021-43e5-aa92-92fdc3f8dee4', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 14, NULL, '14', 15, 250, 'Compare the Loo, Chinook and Foehn winds with respect to their regions of prevalence, their nature and climatic impacts.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('441540d2-4021-43e5-aa92-92fdc3f8dee4', 'Loo, Chinook, and Foehn are all regional, localized winds, but they differ sharply in temperature character and origin despite a shared broad category of ''named local winds.''

**Region of prevalence:** Loo blows across the Indo-Gangetic plains of North India and Pakistan during summer (April-June). Chinook occurs on the eastern (leeward) slopes of the Rocky Mountains in North America (Canada and the US). Foehn occurs on the leeward (typically northern) slopes of the Alps in Europe, the wind type after which this whole category of leeward mountain winds is named.

**Nature:** Loo is a hot, dry, dust-laden wind driven by intense surface heating of the North Indian plains during peak summer -- it is not primarily a mountain-descent wind the way the other two are. Chinook and Foehn share an identical physical mechanism: moist air is forced up the windward slope of a mountain range, cools and loses its moisture as precipitation (orographic rainfall) on that windward side, and then descends the leeward slope as now-dry air that warms rapidly through adiabatic compression -- descending air heats up as atmospheric pressure increases, at a much faster rate (the dry adiabatic lapse rate) than it had cooled while ascending and losing moisture. This is why both are warm, dry winds despite descending FROM colder high-altitude air, an effect often called the ''foehn effect'' generically, after the Alpine original.

**Climatic impact:** Loo causes heatwave conditions and can be directly life-threatening across North India, contributing to the region''s severe pre-monsoon summer heat extremes. Chinook, known locally as a ''snow-eater,'' can raise temperatures dramatically within hours and rapidly melt snow cover, which is agriculturally beneficial (exposing grazing land early) but can also trigger localized flooding from rapid snowmelt. Foehn similarly triggers rapid Alpine snowmelt and has historically been associated with increased avalanche risk and fire hazard in affected valleys, given the sudden shift to warm, dry conditions over previously snow-covered terrain.

The key comparative insight is that Chinook and Foehn are mechanistically identical (the same orographic-descent process under two regional names), while Loo, despite superficially similar hot/dry characteristics, arises from a distinct mechanism (plains surface-heating, not mountain descent) entirely.', 'The critical distinction examiners look for is recognizing that Chinook and Foehn are the SAME phenomenon under two regional names (making a ''compare'' answer that treats all three as three independent mechanisms a real error), while Loo is mechanistically different despite superficial similarity in being hot and dry -- getting this structural point right, not just listing facts about each wind separately, is what separates a strong answer from an average one.', 'UPSC CSE Mains 2026, GS Paper I, Q14 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('cc7ef3a8-d1ea-4516-b2e0-bc3e272ac30a', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 15, NULL, '15', 15, 250, 'Analyze the role of satellite-based technologies in achieving climate-smart agriculture and food security in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('cc7ef3a8-d1ea-4516-b2e0-bc3e272ac30a', 'Climate-smart agriculture requires precise, timely, field-level information at a scale no ground-based survey system can match affordably -- exactly the gap satellite-based technology fills, making it foundational infrastructure for India''s climate-adaptive food-security strategy rather than a peripheral add-on.

Crop monitoring and yield estimation is the most mature application: ISRO''s FASAL (Forecasting Agricultural output using Space, Agrometeorology and Land based observations) programme uses satellite remote sensing to estimate crop area and likely yield well ahead of harvest, informing both procurement planning and early-warning of potential shortfalls -- capability with direct food-security relevance since accurate advance yield estimates let the state pre-position buffer stock and import decisions rather than reacting after a shortfall is already visible.

Drought and stress monitoring uses satellite-derived vegetation and soil-moisture indices to detect crop stress before it becomes visible on the ground, enabling faster, better-targeted drought-relief and crop-insurance response (feeding directly into schemes like Pradhan Mantri Fasal Bima Yojana''s loss-assessment process). Precision agriculture applications -- satellite-guided variable-rate input application, soil-health-linked recommendations -- reduce water and fertilizer overuse, which is itself a climate-adaptation goal given groundwater stress and fertilizer''s carbon footprint. Weather and monsoon forecasting, substantially satellite-data-dependent, allows farmers to time sowing and irrigation decisions around more accurate short-range forecasts, directly reducing climate-related crop loss from mistimed operations.

The real constraint limiting fuller impact is less technological than access-related: satellite data and its downstream advisory products must actually reach small and marginal farmers in a usable, actionable form (often via mobile-based advisory services) -- a data-availability success at the state level does not automatically translate into a farm-level behavioral change unless the last-mile advisory and extension infrastructure is equally well built out, which remains uneven across India.

Satellite technology''s role is therefore best understood as necessary but not sufficient: it supplies the information climate-smart decisions require, but its food-security payoff depends on the extension and advisory systems that convert that information into an actual farmer''s actual decision.', 'Strong answers name real Indian programmes (FASAL, PMFBY''s satellite-linked loss assessment) rather than describing satellite agriculture generically, and end with a genuine limitation (the last-mile advisory gap) rather than presenting the technology as a complete solution on its own.', 'UPSC CSE Mains 2026, GS Paper I, Q15 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c5bddc9e-38e4-4864-bef2-1db86f00864b', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 16, NULL, '16', 15, 250, '"The centre of global trade is gradually shifting from the Atlantic region to the Indo-Pacific region." Examine this statement.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c5bddc9e-38e4-4864-bef2-1db86f00864b', 'The claim reflects a real, measurable, multi-decade shift in global trade''s centre of gravity, driven by the sustained rise of Asian manufacturing and consumption, even as the Atlantic (US-EU) corridor remains individually significant.

The evidence is substantial. China''s emergence as the world''s manufacturing hub and, alongside India, Japan, South Korea, and ASEAN, as a demand centre, has made intra-Asian and trans-Pacific trade volumes rival and in many measures exceed transatlantic volumes. Major container shipping routes now concentrate heavily on Asia-linked corridors (Asia-Europe, trans-Pacific) rather than the historically dominant transatlantic route. Regional trade architecture reflects the same shift: RCEP (Regional Comprehensive Economic Partnership), the world''s largest trade bloc by population and GDP, is entirely Indo-Pacific in membership, while comparable Atlantic-centred mega-deals (a full EU-US trade agreement) have repeatedly stalled. Strategic naming itself reflects the shift -- the widespread adoption of ''Indo-Pacific'' as the operative geopolitical-economic frame (replacing the older ''Asia-Pacific'') by the US, India, Japan, Australia and the EU''s own official documents signals that policymakers themselves now treat this region as the primary arena, not a secondary one.

A fair ''examine'' answer must also note real limits to the shift. The US and EU remain, individually, the largest single-country/bloc economies and among the largest bilateral trade relationships in the world; the shift is in relative share and growth rate, not an absolute Atlantic decline. Financial and monetary architecture (the dollar''s reserve-currency role, the depth of US and European capital markets) remains heavily Atlantic-centred even as physical trade volumes shift eastward, meaning the ''centre of global trade'' is not a single, cleanly-measurable thing -- it depends on whether one measures physical goods trade, financial flows, or currency/settlement infrastructure, and these are shifting at different speeds.

On balance, the statement is substantially correct for goods trade and regional economic architecture, but should be stated as a genuine but partial and uneven shift, not a completed transition away from Atlantic centrality.', 'The strongest answers cite specific evidence (RCEP, shipping-route data, the Indo-Pacific naming shift) rather than asserting the shift impressionistically, and explicitly separate different dimensions of ''centre of trade'' (goods trade versus financial/currency architecture) to avoid overstating a uniform, completed shift.', 'UPSC CSE Mains 2026, GS Paper I, Q16 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('90ce3670-a404-461c-a53f-09e8d97f56cf', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 17, NULL, '17', 15, 250, 'Analyze the major drivers of human-induced land-use changes in India and their geographical consequences.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('90ce3670-a404-461c-a53f-09e8d97f56cf', 'India''s land-use pattern has changed substantially since independence, driven by a small number of major human pressures, each with distinct and measurable geographical consequences.

Urbanization and infrastructure expansion is the most visible driver -- built-up area has grown rapidly around every major city, converting agricultural and forest fringe land at the urban periphery, producing urban heat islands, altered local drainage (increased impervious surface raising flood risk in cities like Chennai and Mumbai), and groundwater table decline from concentrated extraction. Agricultural intensification and the Green Revolution''s spread converted substantial forest, grassland, and wetland area to intensive cultivation, particularly in Punjab, Haryana, and western UP, producing the well-documented consequence of groundwater depletion from paddy-wheat rotation''s high water demand and soil degradation from intensive monocropping and fertilizer overuse. Deforestation for agriculture, mining, and infrastructure -- concentrated in central Indian tribal-belt states (Chhattisgarh, Jharkhand, Odisha) and parts of the Northeast -- has produced measurable biodiversity loss, increased soil erosion on deforested slopes, and locally altered rainfall patterns given forests'' role in regional moisture recycling. Mining activity, again concentrated in the mineral-rich central Indian belt, has produced direct land degradation (open-cast mining scars, overburden dumping) and downstream water-quality impacts from runoff.

A geographically precise answer should note these drivers are not evenly distributed -- the specific land-use change and its consequence differs by region: coastal and metro peripheries see urbanization-driven change, the Indo-Gangetic plain sees agriculture-driven groundwater stress, and the central Indian tribal belt sees mining- and deforestation-driven degradation concentrated in the same relatively narrow geographical zone.

The cumulative geographical consequence across all these drivers is a measurable net loss of India''s natural land-cover buffer -- forest, wetland, and grassland -- that previously provided flood absorption, groundwater recharge, and biodiversity habitat, meaning many of today''s climate-vulnerability hotspots (urban flooding, groundwater-stressed agrarian belts) are substantially a product of land-use decisions made over the preceding decades, not only of changing rainfall patterns themselves.', 'Strong answers organize by distinct driver (urbanization, agricultural intensification, deforestation, mining) each with its own specific geographical consequence and specific Indian region, rather than a single undifferentiated list of ''land-use changes are bad for the environment.'' Naming specific regions (Indo-Gangetic plain, central Indian tribal belt) for each driver is what earns the ''geographical consequences'' half of the question credit.', 'UPSC CSE Mains 2026, GS Paper I, Q17 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('aa12e150-4e87-4b0d-a38d-b9057ac09738', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 18, NULL, '18', 15, 250, 'Is caste disappearing in urban India? Illustrate your answer with examples.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('aa12e150-4e87-4b0d-a38d-b9057ac09738', 'Caste is not disappearing in urban India, but its visible form has changed substantially -- it persists less as overt, publicly enforced ritual hierarchy and more as an underlying structure shaping marriage, social networks, and economic opportunity in ways that are less immediately visible but still measurable.

Evidence that caste''s traditional public visibility has genuinely declined: urban residential and workplace interaction routinely crosses caste lines in ways rural social structure historically restricted, overt untouchability practice (temple entry restriction, physical segregation) has substantially receded in cities, and urban anonymity reduces the ability of traditional caste-based social sanction to operate the way it does in a smaller, more caste-visible rural community.

Evidence that caste persists in transformed but still-substantial form: matrimonial patterns remain overwhelmingly endogamous even in urban, educated populations -- matrimonial advertisements and platforms (both print and digital, such as caste-specific sections on major matrimonial websites) continue to organize explicitly around caste category as a primary search criterion, showing the institution persists precisely where it is least publicly visible or debated. Studies of urban hiring and rental-housing markets have documented measurable caste-based discrimination through correspondence-audit methods (identical resumes/applications with different caste-signaling names receiving different response rates), indicating caste continues to function as an economic filter even absent any explicit acknowledgment. Political mobilization along caste lines (caste-based parties, reservation politics) remains a live and often dominant feature of urban as much as rural electoral behaviour, showing caste identity continues to organize collective political action, not merely private social life.

The honest answer is therefore not a simple yes or no: caste''s overt ritual and spatial expression has genuinely weakened in urban India, but its function as a structuring principle for marriage, economic opportunity, and political mobilization persists, often precisely because it now operates through private choices (who to marry, whom to shortlist for a rental) that are harder to regulate or even observe than the older public forms of discrimination were.', 'The question specifically asks for a yes/no engagement plus examples -- an answer that only describes caste''s history without taking a clear, evidenced position on whether it is ''disappearing'' misses the direct instruction. The strongest answers distinguish between caste''s declining PUBLIC/ritual visibility and its persisting PRIVATE function (marriage, hiring, politics), which is the actual nuance the question is testing for.', 'UPSC CSE Mains 2026, GS Paper I, Q18 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('31db5c61-45b5-4dd1-ac76-02cc5155b197', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 19, NULL, '19', 15, 250, 'Critically examine the challenges of demographic transition in contemporary India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('31db5c61-45b5-4dd1-ac76-02cc5155b197', 'India is passing through demographic transition unevenly across states, and this unevenness -- not the transition itself -- is the source of its most pressing contemporary challenges.

Southern and some western states (Kerala, Tamil Nadu, Andhra Pradesh, Karnataka) have already reached below-replacement fertility levels and are moving toward the transition''s later stages, facing an aging population, a shrinking working-age share, and rising old-age dependency -- challenges structurally similar to those of developed economies, arriving in India before per-capita income has reached comparably developed-economy levels, a genuinely difficult combination (''growing old before growing rich''). Northern and some central states (Bihar, Uttar Pradesh, Madhya Pradesh) remain earlier in the transition, with higher fertility and a still-expanding working-age population, giving them a longer runway for the demographic dividend -- but only if education, skilling, and job creation keep pace with this expanding cohort, which has not been uniformly the case.

This creates a genuine national coordination challenge distinct from either region''s problem in isolation: labour migration from the earlier-transition, high-fertility states to the later-transition, labour-short southern states is already a significant and growing internal migration pattern, with real social-integration and political tension implications (language, local-versus-migrant political friction) that are likely to intensify as the gap widens rather than close on its own.

The demographic dividend itself -- often cited as India''s central economic opportunity -- is not automatic; it requires the expanding working-age population to actually be employed productively, which depends on education quality, skill development, and job creation keeping pace with population growth, a alignment that has been inconsistent to date (youth unemployment and underemployment remain persistently high in several high-fertility states specifically). A dividend that is not actually captured through employment simply becomes a larger dependent or underemployed population instead, converting a potential asset into a potential liability.

The critical insight, then, is that India''s demographic transition is less a single national challenge than several simultaneous, out-of-sync regional transitions, whose interaction (migration, dividend capture, aging) is itself the primary policy challenge, more than any single state''s demographic stage in isolation.', '''Critically examine'' rewards identifying the regional asymmetry (South ageing while North still young) as the central analytical point, rather than describing India''s demographic transition as one uniform national process. Naming the demographic-dividend''s conditionality (it requires jobs to actually materialize, not just a young population existing) is what distinguishes a critical answer from a purely descriptive one.', 'UPSC CSE Mains 2026, GS Paper I, Q19 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ea763086-71da-426b-8b6b-92493ff1fbfe', '5acc6eef-cc20-45f0-be8e-c57f6618d943', 20, NULL, '20', 15, 250, 'Evaluate the impact of globalization on Indian youths with reference to social, political, economic and cultural spheres.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ea763086-71da-426b-8b6b-92493ff1fbfe', 'Globalization''s impact on Indian youth since the 1991 liberalization has been genuinely transformative across all four dimensions the question names, with real gains alongside real, specific costs in each.

**Economic:** globalization opened IT, BPO, e-commerce, and gig-economy sectors that did not exist in the pre-liberalization economy, giving urban, educated youth substantially wider career options and, for a significant segment, income mobility their parents'' generation did not have access to. The cost is uneven distribution -- these gains have concentrated heavily in urban, English-educated, already-advantaged youth, while rural and less-educated youth face a starker gig-economy/informal-sector reality with far less of the security or mobility globalization''s success stories represent.

**Social:** exposure to global media, international education and travel, and cross-border digital communication has visibly shifted youth attitudes on gender roles, marriage timing, and career choice away from strictly traditional family expectations in many urban settings, alongside a genuine and often-discussed rise in individualism relative to earlier joint-family-centred social organization -- a real social gain in personal autonomy for many, alongside real inter-generational family tension where expectations have not shifted at the same pace.

**Political:** globalized information access and social media have made Indian youth more aware of global political movements and more willing to organize digitally around domestic causes (visible in various youth-led protest movements over the past decade), a genuine expansion of political engagement channels beyond traditional party structures -- though this same environment has also made youth more exposed to globally-circulating misinformation and polarized political content.

**Cultural:** globalization has produced genuine cultural hybridity -- fusion cuisine, music, and fashion blending global and Indian idioms into something distinctly new, alongside youth-led revivals of regional and traditional cultural forms enabled by the same global platforms (a folk art form finding new life and audience through social media, for instance). The frequently-voiced concern about globalization simply erasing Indian culture in favour of a homogenized Western one is only partly borne out -- the more accurate pattern is hybridization and selective adaptation, not wholesale replacement.

On balance, globalization''s impact on Indian youth is best evaluated as a genuine expansion of opportunity and exposure, unevenly distributed by class, geography, and education, producing real gains and real new tensions simultaneously rather than a straightforwardly positive or negative verdict.', 'The question explicitly structures itself across four named spheres -- answers that address all four with genuinely distinct content (not the same point restated four ways) score higher than answers collapsing them into one general discussion. ''Evaluate'' expects a genuine balanced verdict at the end, not just a list of effects with no overall judgment.', 'UPSC CSE Mains 2026, GS Paper I, Q20 (exam held 22 August 2026). Verified verbatim against two independent sources matching almost word-for-word: Drishti IAS''s "UPSC Mains 2026 GS Paper 1 Question Paper" page and Insights on India''s equivalent page.');
